/* Offline Markdown Workbench local syntax-highlighting compatibility layer. */
(function(w){var e=function(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')};w.hljs=w.hljs||{};w.hljs.version='offline-compat-1.0';w.hljs.highlight=function(code,o){return{value:e(code),language:o&&o.language||'text',relevance:0}};w.hljs.highlightAuto=function(code){return{value:e(code),language:'text',relevance:0}}})(window);
